import csv
import io
import json

_FIELDS = ("id", "name")


def _normalize(rows):
    """Return new records holding only FIELDS, in input order.

    Missing or None values become ''; every other value is stringified.
    Consumes ``rows`` exactly once and never mutates its items.
    """
    return [
        {key: "" if row.get(key) is None else str(row[key]) for key in _FIELDS}
        for row in rows
    ]


def _serialize_csv(records):
    buffer = io.StringIO(newline="")
    writer = csv.writer(buffer, lineterminator="\n")
    writer.writerow(_FIELDS)
    for record in records:
        writer.writerow([record[key] for key in _FIELDS])
    return buffer.getvalue()


def _serialize_json(records):
    return json.dumps(records, ensure_ascii=False, separators=(",", ":"))


_SERIALIZERS = {
    "csv": _serialize_csv,
    "json": _serialize_json,
}


def export_rows(rows, format):
    """Export ``rows`` as 'csv' or 'json'. Raises ValueError for other formats."""
    if not isinstance(format, str) or format not in _SERIALIZERS:
        raise ValueError(f"unsupported format: {format!r}")
    return _SERIALIZERS[format](_normalize(rows))
