import sys, copy, importlib
def load(root):
    for m in [k for k in sys.modules if k == "src" or k.startswith("src.")]:
        del sys.modules[m]
    sys.path.insert(0, root)
    try:
        return importlib.import_module("src.dispatcher"), importlib.import_module("src.csv_exporter"), importlib.import_module("src.json_exporter")
    finally:
        sys.path.remove(root)

old = load("/tmp/orig")
old_mods = {k: v for k, v in sys.modules.items() if k.startswith("src")}
new = load("/workspace")
assert old[0].__file__ != new[0].__file__

cases = {
    "empty": lambda: [],
    "basic": lambda: [{"id": 1, "name": "Alice"}],
    "none_missing": lambda: [{"id": None}, {"name": None}, {}, {"id": 0, "name": False}],
    "non_str": lambda: [{"id": 3.5, "name": ["a", 1]}, {"id": True, "name": {"k": "v"}}],
    "extra_keys": lambda: [{"id": 1, "name": "x", "secret": "y", "zz": 9}],
    "quoting": lambda: [{"id": 'a,b', "name": 'say "hi"'}, {"id": "line\nbreak", "name": "cr\rhere"}, {"id": " lead", "name": ""}],
    "unicode": lambda: [{"id": "é", "name": "日本語 😀"}, {"id": "\u2028", "name": "\\\""}],
    "order": lambda: [{"name": "b", "id": 2}, {"name": "a", "id": 1}, {"id": 3, "name": "c"}],
    "generator": lambda: ({"id": i, "name": f"n{i}"} for i in range(4)),
    "iter_of_map": lambda: iter([{"id": 1, "name": "q"}]),
}
fails = 0
for label, mk in cases.items():
    for fmt, fn_idx in (("csv", 1), ("json", 2)):
        o = old[fn_idx].__dict__[f"export_{fmt}"](mk())
        n = new[fn_idx].__dict__[f"export_{fmt}"](mk())
        d = new[0].export(mk(), fmt)
        if not (o == n == d and type(o) is type(n)):
            fails += 1
            print("MISMATCH", label, fmt, repr(o), repr(n), repr(d))
        else:
            print("ok", label, fmt, repr(n)[:70])

# mutation: inputs untouched
src = [{"id": 1, "name": "A", "extra": 2}, {"id": None}]
snap = copy.deepcopy(src)
new[1].export_csv(src); new[2].export_json(src); new[0].export(src, "csv")
assert src == snap, "input mutated"
# one-shot iterable consumed exactly once
calls = []
def gen():
    for r in [{"id": 1}, {"id": 2}]:
        calls.append(1); yield r
new[2].export_json(gen()); assert len(calls) == 2
# dispatcher errors and unsupported format
for bad in ["xml", "CSV", "", None, ["csv"]]:
    for fn in (lambda r, f=bad: new[0].export(r, f), lambda r, f=bad: __import__("src.exporter", fromlist=["x"]).export_rows(r, f)):
        try:
            fn([{"id": 1}]); fails += 1; print("no error for", bad)
        except ValueError as e:
            pass
    try:
        old[0].export([], bad); print("old no error", bad)
    except ValueError: pass
# unsupported format must not consume rows
consumed = []
def g2():
    consumed.append(1); yield {"id": 1}
try: __import__("src.exporter", fromlist=["x"]).export_rows(g2(), "xml")
except ValueError: pass
assert consumed == [], "rows consumed on bad format"
print("FAILS", fails)
EOF
